export default JSON.parse(
  "{\n  \"workId\": \"xunzi\",\n  \"chapter\": {\n    \"id\": \"xunzi_ch-15\",\n    \"workId\": \"xunzi\",\n    \"order\": 15,\n    \"title\": \"議兵\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 16,\n    \"passageIds\": [\n      \"xunzi_ch-15_p-1\",\n      \"xunzi_ch-15_p-2\",\n      \"xunzi_ch-15_p-3\",\n      \"xunzi_ch-15_p-4\",\n      \"xunzi_ch-15_p-5\",\n      \"xunzi_ch-15_p-6\",\n      \"xunzi_ch-15_p-7\",\n      \"xunzi_ch-15_p-8\",\n      \"xunzi_ch-15_p-9\",\n      \"xunzi_ch-15_p-10\",\n      \"xunzi_ch-15_p-11\",\n      \"xunzi_ch-15_p-12\",\n      \"xunzi_ch-15_p-13\",\n      \"xunzi_ch-15_p-14\",\n      \"xunzi_ch-15_p-15\",\n      \"xunzi_ch-15_p-16\",\n      \"xunzi_ch-15_p-17\",\n      \"xunzi_ch-15_p-18\",\n      \"xunzi_ch-15_p-19\",\n      \"xunzi_ch-15_p-20\",\n      \"xunzi_ch-15_p-21\",\n      \"xunzi_ch-15_p-22\",\n      \"xunzi_ch-15_p-23\",\n      \"xunzi_ch-15_p-24\",\n      \"xunzi_ch-15_p-25\",\n      \"xunzi_ch-15_p-26\",\n      \"xunzi_ch-15_p-27\"\n    ],\n    \"tags\": [\n      \"儒家\",\n      \"性惡論\",\n      \"禮樂\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"xunzi_ch-15_p-1\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 1,\n      \"canonicalText\": \"臨武君與孫卿子議兵於趙孝成王前，王曰：請問兵要？\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-1_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"臨武君與荀子（孫卿子）在趙孝成王面前共同討論用兵之法。趙王問道：「請問用兵打仗的根本要領是什麼？」\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「臨武君與孫卿子議兵於趙孝成王前，王曰：請問兵要」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「臨」、「武」、「君」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「臨武君與孫卿子議兵於趙孝成王前王曰請問兵要」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「臨武君與孫卿子議兵於趙孝成王前，王曰：請問兵要」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-2\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 2,\n      \"canonicalText\": \"臨武君對曰：上得天時，下得地利，觀敵之變動，後之發，先之至，此用兵之要術也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-2_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"臨武君對說道：上得天時，下得地利，觀敵的變動，後的發，先的至，此用兵的要術啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「臨武君對曰：上得天時，下得地利，觀敵之變動，後之發，先之至，此用兵之要術也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「臨」、「武」、「君」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「臨武君對曰上得天時下得地利觀敵之變動後之發先之至」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「臨武君對曰：上得天時，下得地利，觀敵之變動，後之發，先之至，此用兵之要術也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-3\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 3,\n      \"canonicalText\": \"孫卿子曰：不然！臣所聞古之道，凡用兵攻戰之本，在乎壹民。弓矢不調，則羿不能以中微；六馬不和，則造父不能以致遠；士民不親附，則湯武不能以必勝也。故善附民者，是乃善用兵者也。故兵要在乎善附民而已。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-3_s-1\",\n        \"xunzi_ch-15_p-3_s-2\",\n        \"xunzi_ch-15_p-3_s-3\",\n        \"xunzi_ch-15_p-3_s-4\",\n        \"xunzi_ch-15_p-3_s-5\",\n        \"xunzi_ch-15_p-3_s-6\",\n        \"xunzi_ch-15_p-3_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孫卿子說道：不然！臣所聞古的道，凡用兵攻戰的本，在乎壹民。弓矢不調，則羿不能以中微；六馬不和，則造父不能以致遠；士民不親附，則湯武不能以必勝啊。所以善附民的人或事，是乃善用兵的人或事啊。所以兵要在乎善附民而且已。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孫卿子曰：不然」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孫」、「卿」、「子」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孫卿子曰不然臣所聞古之道凡用兵攻戰之本在乎壹民弓」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「臣所聞古之道，凡用兵攻戰之本，在乎壹民」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-4\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 4,\n      \"canonicalText\": \"臨武君曰：不然。兵之所貴者埶利也，所行者變詐也。善用兵者，感忽悠闇，莫知其所從出。孫吳用之無敵於天下，豈必待附民哉！\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-4_s-1\",\n        \"xunzi_ch-15_p-4_s-2\",\n        \"xunzi_ch-15_p-4_s-3\",\n        \"xunzi_ch-15_p-4_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"臨武君說道：不然。兵的所貴的人或事埶利啊，所行的人或事變詐啊。善用兵的人或事，感忽悠闇，莫知他的所從出。孫吳用的無敵於天下，豈必待附民哉！\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「臨武君曰：不然」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「臨」、「武」、「君」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「臨武君曰不然兵之所貴者埶利也所行者變詐也善用兵者」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「兵之所貴者埶利也，所行者變詐也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 5,\n      \"canonicalText\": \"孫卿子曰：不然。臣之所道，仁者之兵，王者之志也。君之所貴，權謀埶利也；所行，攻奪變詐也；諸侯之事也。仁人之兵，不可詐也；彼可詐者，怠慢者也，路亶者也，君臣上下之間，渙然有離德者也。故以桀詐桀，猶巧拙有幸焉。以桀詐堯，譬之：若以卵投石，以指撓沸；若赴水火，入焉焦沒耳。故仁人上下，百將一心，三軍同力；臣之於君也，下之於上也，若子之事父，弟之事兄，若手臂之扞頭目而覆胸腹也，詐而襲之，與先驚而後擊之，一也。且仁人之用十里之國，則將有百里之聽；用百里之國，則將有千里之聽；用千里之國，則將有四海之聽，必將聰明警戒和傳而一。故仁人之兵，聚則成卒，散則成列，延則若莫邪之長刃，嬰之者斷；兌則若莫邪之利鋒，當之者潰，圜居而方止，則若盤石然，觸之者角摧，案角鹿埵隴種東籠而退耳。且夫暴國之君，將誰與至哉？彼其所與至者，必其民也，而其民之親我歡若父母，其好我芬若椒蘭，彼反顧其上，則若灼黥，若讎仇；人之情，雖桀蹠，豈又肯為其所惡，賊其所好者哉！是猶使人之子孫自賊其父母也，彼必將來告之，夫又何可詐也！故仁人用國日明，諸侯先順者安，後順者危，慮敵之者削，反之者亡。《詩》曰：「武王載發，有虔秉鉞；如火烈烈，則莫我敢遏。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-5_s-1\",\n        \"xunzi_ch-15_p-5_s-2\",\n        \"xunzi_ch-15_p-5_s-3\",\n        \"xunzi_ch-15_p-5_s-4\",\n        \"xunzi_ch-15_p-5_s-5\",\n        \"xunzi_ch-15_p-5_s-6\",\n        \"xunzi_ch-15_p-5_s-7\",\n        \"xunzi_ch-15_p-5_s-8\",\n        \"xunzi_ch-15_p-5_s-9\",\n        \"xunzi_ch-15_p-5_s-10\",\n        \"xunzi_ch-15_p-5_s-11\",\n        \"xunzi_ch-15_p-5_s-12\",\n        \"xunzi_ch-15_p-5_s-13\",\n        \"xunzi_ch-15_p-5_s-14\",\n        \"xunzi_ch-15_p-5_s-15\",\n        \"xunzi_ch-15_p-5_s-16\",\n        \"xunzi_ch-15_p-5_s-17\",\n        \"xunzi_ch-15_p-5_s-18\",\n        \"xunzi_ch-15_p-5_s-19\",\n        \"xunzi_ch-15_p-5_s-20\",\n        \"xunzi_ch-15_p-5_s-21\",\n        \"xunzi_ch-15_p-5_s-22\",\n        \"xunzi_ch-15_p-5_s-23\",\n        \"xunzi_ch-15_p-5_s-24\",\n        \"xunzi_ch-15_p-5_s-25\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孫卿子說道：不然。臣的所道，仁愛之德的人或事的兵，王的人或事的志啊。君的所貴，權謀埶利啊；所行，攻奪變詐啊；諸侯的事啊。仁愛之德人的兵，不可詐啊；彼可詐的人或事，怠慢的人或事啊，路亶的人或事啊，君臣上下的間，渙然有離德行修養的人或事啊。所以以桀詐桀，猶巧拙有幸焉。以桀詐堯，譬的：若以卵投石，以指撓沸；若赴水火，入焉焦沒耳。所以仁愛之德人上下，百將一心，三軍同力；臣的於君啊，下的於上啊，若子的事父，弟的事兄，若手臂的扞頭目而且覆胸腹啊，詐而且襲的，與先驚而且後擊的，一啊。且仁愛之德人的用十里的國，則將有百里的聽；用百里的國，則將有千里的聽；用千里的國，則將有四海的聽，必將聰明警戒和傳而且一。所以仁愛之德人的兵，聚則成卒，散則成列，延則若莫邪的長刃，嬰的的人或事斷；兌則若莫邪的利鋒，當的的人或事潰，圜居而且方止，則若盤石然，觸的的人或事角摧，案角鹿埵隴種東籠而且退耳。再的人或事況且暴國的君，將誰與至哉？彼他的所與至的人或事，必他的民啊，而且他的民的親我歡若父母，他的好我芬若椒蘭，彼反顧他的上，則若灼黥，若讎仇；人的情，雖桀蹠，豈又肯為他的所惡，賊他的所好的人或事哉！是猶使人的子孫自賊他的父母啊，彼必將來告的，夫又何可詐啊！所以仁愛之德人用國日明，諸侯先順的人或事安，後順的人或事危，慮敵的的人或事削，反的的人或事亡。《詩》說道：武王載發，有虔秉鉞；如火烈烈，則莫我敢遏。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孫卿子曰：不然」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孫」、「卿」、「子」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孫卿子曰不然臣之所道仁者之兵王者之志也君之所貴權」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「臣之所道，仁者之兵，王者之志也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-6\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 6,\n      \"canonicalText\": \"孝成王、臨武君曰：善！請問王者之兵，設何道何行而可？\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-6_s-1\",\n        \"xunzi_ch-15_p-6_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孝成王、臨武君說道：善！請問王的人或事的兵，設何道何行而且可？\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孝成王、臨武君曰：善」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孝」、「成」、「王」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孝成王臨武君曰善請問王者之兵設何道何行而可」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「請問王者之兵，設何道何行而可」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 7,\n      \"canonicalText\": \"孫卿子曰：凡在大王，將率末事也。臣請遂道王者諸侯強弱存亡之效，安危之埶：君賢者其國治，君不能者其國亂；隆禮貴義者其國治，簡禮賤義者其國亂；治者強，亂者弱，是強弱之本也。上足卬則下可用也，上不卬則下不可用也；下可用則強，下不可用則弱，是強弱之常也。隆禮效功，上也；重祿貴節，次也；上功賤節，下也，是強弱之凡也。好士者強，不好士者弱；愛民者強，不愛民者弱；政令信者強，政令不信者弱；民齊者強，民不齊者弱；賞重者強，賞輕者弱；刑威者強，刑侮者弱；械用兵革攻完便利者強，械用兵革窳楛不便利者弱。重用兵者強，輕用兵者弱；權出一者強，權出二者弱，是強弱之常也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-7_s-1\",\n        \"xunzi_ch-15_p-7_s-2\",\n        \"xunzi_ch-15_p-7_s-3\",\n        \"xunzi_ch-15_p-7_s-4\",\n        \"xunzi_ch-15_p-7_s-5\",\n        \"xunzi_ch-15_p-7_s-6\",\n        \"xunzi_ch-15_p-7_s-7\",\n        \"xunzi_ch-15_p-7_s-8\",\n        \"xunzi_ch-15_p-7_s-9\",\n        \"xunzi_ch-15_p-7_s-10\",\n        \"xunzi_ch-15_p-7_s-11\",\n        \"xunzi_ch-15_p-7_s-12\",\n        \"xunzi_ch-15_p-7_s-13\",\n        \"xunzi_ch-15_p-7_s-14\",\n        \"xunzi_ch-15_p-7_s-15\",\n        \"xunzi_ch-15_p-7_s-16\",\n        \"xunzi_ch-15_p-7_s-17\",\n        \"xunzi_ch-15_p-7_s-18\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孫卿子說道：凡在大王，將率末事啊。臣請遂道王的人或事諸侯強弱存亡的效，安危的埶：君賢的人或事他的國治，君不能的人或事他的國亂；隆禮道義正道道德行修養規程貴道義正道的人或事他的國治，簡禮道義正道道德行修養規程賤道義正道的人或事他的國亂；治的人或事強，亂的人或事弱，是強弱的本啊。上足卬則下可用啊，上不卬則下不可用啊；下可用則強，下不可用則弱，是強弱的常啊。隆禮道義正道道德行修養規程效功，上啊；重祿貴節，次啊；上功賤節，下啊，是強弱的凡啊。好士的人或事強，不好士的人或事弱；愛民的人或事強，不愛民的人或事弱；政令信的人或事強，政令不信的人或事弱；民齊的人或事強，民不齊的人或事弱；賞重的人或事強，賞輕的人或事弱；刑威的人或事強，刑侮的人或事弱；械用兵革攻完便利的人或事強，械用兵革窳楛不便利的人或事弱。重用兵的人或事強，輕用兵的人或事弱；權出一的人或事強，權出二的人或事弱，是強弱的常啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孫卿子曰：凡在大王，將率末事也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孫」、「卿」、「子」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孫卿子曰凡在大王將率末事也臣請遂道王者諸侯強弱存」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「臣請遂道王者諸侯強弱存亡之效，安危之埶：君賢者其國治，君不能者其國亂」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-8\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 8,\n      \"canonicalText\": \"齊人隆技擊，其技也，得一首者，則賜贖錙金，無本賞矣。是事小敵毳，則偷可用也，事大敵堅，則渙然離耳。若飛鳥然，傾側反覆無日，是亡國之兵也，兵莫弱是矣。是其去賃市傭而戰之幾矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-8_s-1\",\n        \"xunzi_ch-15_p-8_s-2\",\n        \"xunzi_ch-15_p-8_s-3\",\n        \"xunzi_ch-15_p-8_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊人隆技擊，他的技啊，得一首的人或事，則賜贖錙金，無本賞矣。是事小敵毳，則偷可用啊，事大敵堅，則渙然離耳。若飛鳥然，傾側反覆無日，是亡國的兵啊，兵莫弱是矣。是他的去賃市傭而且戰的幾矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「齊人隆技擊，其技也，得一首者，則賜贖錙金，無本賞矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「齊」、「人」、「隆」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「齊人隆技擊其技也得一首者則賜贖錙金無本賞矣是事小」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「是事小敵毳，則偷可用也，事大敵堅，則渙然離耳」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-9\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 9,\n      \"canonicalText\": \"魏氏之武卒，以度取之，衣三屬之甲，操十二石之弩，負服矢五十個，置戈其上，冠冑帶劍，贏三日之糧，日中而趨百里，中試則復其戶，利其田宅，是數年而衰，而未可奪也，改造則不易周也，是故地雖大，其稅必寡，是危國之兵也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-9_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"魏氏的武卒，以度取的，衣三屬的甲，操十二石的弩，負服矢五十個，置戈他的上，冠冑帶劍，贏三日的糧，日中而且趨百里，中試則復他的戶，利他的田宅，是數年而且衰，而且未可奪啊，改造則不易周啊，正因為如此地雖大，他的稅必寡，是危國的兵啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「魏氏之武卒，以度取之，衣三屬之甲，操十二石之弩，負服矢五十個，置戈其上，冠冑帶劍，贏三日之糧，日中而趨百里，中試則復其戶，利其田宅，是數年而衰，而未可奪也，改造則不易周也，是故地雖大，其稅必寡，是危國之兵也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「魏」、「氏」、「武」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「魏氏之武卒以度取之衣三屬之甲操十二石之弩負服矢五」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「魏氏之武卒，以度取之，衣三屬之甲，操十二石之弩，負服矢五十個，置戈其上，冠冑帶劍，贏三日之糧，日中而趨百里，中試則復其戶，利其田宅，是數年而衰，而未可奪也，改造則不易周也，是故地雖大，其稅必寡，是危國之兵也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-10\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 10,\n      \"canonicalText\": \"秦人其生民郟阨，其使民也酷烈，劫之以埶，隱之以阨，忸之以慶賞，酋之以刑罰，使天下之民，所以要利於上者，非鬥無由也。阨而用之，得而後功之，功賞相長也，五甲首而隸五家，是最為眾強長久，多地以正，故四世有勝，非幸也，數也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-10_s-1\",\n        \"xunzi_ch-15_p-10_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"秦人他的生民郟阨，他的使民啊酷烈，劫的以埶，隱的以阨，忸的以慶賞，酋的以刑罰，使天下的民，所以要利於上的人或事，絕不是鬥無由啊。阨而且用的，得而且後功的，功賞相長啊，五甲首而且隸五家，是最為眾強長久，多地以正，所以四世有勝，絕不是幸啊，數啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「秦人其生民郟阨，其使民也酷烈，劫之以埶，隱之以阨，忸之以慶賞，酋之以刑罰，使天下之民，所以要利於上者，非鬥無由也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「秦」、「人」、「生」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「秦人其生民郟阨其使民也酷烈劫之以埶隱之以阨忸之以」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「阨而用之，得而後功之，功賞相長也，五甲首而隸五家，是最為眾強長久，多地以正，故四世有勝，非幸也，數也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 11,\n      \"canonicalText\": \"故齊之技擊，不可以遇魏氏之武卒；魏氏之武卒，不可以遇秦之銳士；秦之銳士，不可以當桓文之節制；桓文之節制，不可以敵湯武之仁義；有遇之者，若以焦熬投石焉。兼是數國者，皆幹賞蹈利之兵也，傭徒鬻賣之道也，未有貴上安制綦節之理也。諸侯有能微妙之以節，則作而兼殆之耳。故招近募選，隆埶詐，尚功利，是漸之也；禮義教化，是齊之也。故以詐遇詐，猶有巧拙焉；以詐遇齊，闢之猶以錐刀墮太山也，非天下之愚人莫敢試。故王者之兵不試。湯武之誅桀紂也，拱挹指麾，而強暴之國莫不趨使，誅桀紂若誅獨夫。故泰誓曰：「獨夫紂。」此之謂也。故兵大齊則制天下，小齊則治鄰敵。若夫招近募選，隆埶詐，尚功利之兵，則勝不勝無常，代翕代張，代存代亡，相為雌雄耳矣。夫是之謂盜兵，君子不由也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-11_s-1\",\n        \"xunzi_ch-15_p-11_s-2\",\n        \"xunzi_ch-15_p-11_s-3\",\n        \"xunzi_ch-15_p-11_s-4\",\n        \"xunzi_ch-15_p-11_s-5\",\n        \"xunzi_ch-15_p-11_s-6\",\n        \"xunzi_ch-15_p-11_s-7\",\n        \"xunzi_ch-15_p-11_s-8\",\n        \"xunzi_ch-15_p-11_s-9\",\n        \"xunzi_ch-15_p-11_s-10\",\n        \"xunzi_ch-15_p-11_s-11\",\n        \"xunzi_ch-15_p-11_s-12\",\n        \"xunzi_ch-15_p-11_s-13\",\n        \"xunzi_ch-15_p-11_s-14\",\n        \"xunzi_ch-15_p-11_s-15\",\n        \"xunzi_ch-15_p-11_s-16\",\n        \"xunzi_ch-15_p-11_s-17\",\n        \"xunzi_ch-15_p-11_s-18\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以齊的技擊，不可以遇魏氏的武卒；魏氏的武卒，不可以遇秦的銳士；秦的銳士，不可以當桓文的節制；桓文的節制，不可以敵湯武的仁愛之德道義正道；有遇的的人或事，若以焦熬投石焉。兼是數國的人或事，皆幹賞蹈利的兵啊，傭徒鬻賣的道啊，未有貴上安制綦節的理啊。諸侯有能微妙的以節，則作而且兼殆的耳。所以招近募選，隆埶詐，尚功利，是漸的啊；禮道義正道道德行修養規程道義正道教化，是齊的啊。所以以詐遇詐，猶有巧拙焉；以詐遇齊，闢的猶以錐刀墮太山啊，絕不是天下的愚人莫敢試。所以王的人或事的兵不試。湯武的誅桀紂啊，拱挹指麾，而且強暴的國莫不趨使，誅桀紂若誅獨夫。所以泰誓說道：獨夫紂。此的謂啊。所以兵大齊則制天下，小齊則治鄰敵。至於談到那招近募選，隆埶詐，尚功利的兵，則勝不勝無常，代翕代張，代存代亡，相為雌雄耳矣。這就是儒家所說的盜兵，君子不由啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「故齊之技擊，不可以遇魏氏之武卒」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「齊」、「技」、「擊」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故齊之技擊不可以遇魏氏之武卒魏氏之武卒不可以遇秦」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「魏氏之武卒，不可以遇秦之銳士」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-12\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 12,\n      \"canonicalText\": \"故齊之田單，楚之莊蹻，秦之衛鞅，燕之繆蟣，是皆世俗所謂善用兵者也，是其巧拙強弱，則未有以相君也。若其道一也，未及和齊也；掎契司詐，權謀傾覆，未免盜兵也。齊桓、晉文、楚莊、吳闔閭、越勾踐是皆和齊之兵也，可謂入其域矣，然而未有本統也，故可以霸而不可以王；是強弱之效也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-12_s-1\",\n        \"xunzi_ch-15_p-12_s-2\",\n        \"xunzi_ch-15_p-12_s-3\",\n        \"xunzi_ch-15_p-12_s-4\",\n        \"xunzi_ch-15_p-12_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以齊的田單，楚的莊蹻，秦的衛鞅，燕的繆蟣，是皆世俗所謂善用兵的人或事啊，是他的巧拙強弱，則未有以相君啊。若他的道一啊，未及和齊啊；掎契司詐，權謀傾覆，未免盜兵啊。齊桓、晉文、楚莊、吳闔閭、越勾踐是皆和齊的兵啊，可謂入他的域矣，然而且未有本統啊，所以可以霸而且不可以王；是強弱的效啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「故齊之田單，楚之莊蹻，秦之衛鞅，燕之繆蟣，是皆世俗所謂善用兵者也，是其巧拙強弱，則未有以相君也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「齊」、「田」、「單」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故齊之田單楚之莊蹻秦之衛鞅燕之繆蟣是皆世俗所謂善」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「若其道一也，未及和齊也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-13\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 13,\n      \"canonicalText\": \"孝成王、臨武君曰善！請問為將？\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-13_s-1\",\n        \"xunzi_ch-15_p-13_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孝成王、臨武君說道：善！請問為將？\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孝成王、臨武君曰善」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孝」、「成」、「王」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孝成王臨武君曰善請問為將」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「請問為將」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 14,\n      \"canonicalText\": \"孫卿子曰：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，事至無悔而止矣，成不可必也。故制號政令欲嚴以威，慶賞刑罰欲必以信，處舍收藏欲周以固，徙舉進退欲安以重，欲疾以速；窺敵觀變欲潛以深，欲伍以參；遇敵決戰必道吾所明，無道吾所疑：夫是之謂六術。無欲將而惡廢，無急勝而忘敗，無威內而輕外，無見利而不顧其害，凡慮事欲孰而用財欲泰：夫是之謂五權。所以不受命於主有三：可殺而不可使處不完，可殺而不可使擊不勝，可殺而不可使欺百姓：夫是之謂三至。凡受命於主而行三軍，三軍既定，百官得序，羣物皆正，則主不能喜，敵不能怒：夫是之謂至臣。慮必先事，而申之以敬，慎終如始，終始如一：夫是之謂大吉。凡百事之成也，必在敬之；其敗也，必在慢之。故敬勝怠則吉，怠勝敬則滅；計勝欲則從，欲勝計則兇。戰如守，行如戰，有功如幸，敬謀無壙，敬事無壙，敬吏無壙，敬眾無壙，敬敵無壙：夫是之謂五無壙。謹行此六術、五權、三至，而處之以恭敬無壙，夫是之謂天下之將，則通於神明矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-14_s-1\",\n        \"xunzi_ch-15_p-14_s-2\",\n        \"xunzi_ch-15_p-14_s-3\",\n        \"xunzi_ch-15_p-14_s-4\",\n        \"xunzi_ch-15_p-14_s-5\",\n        \"xunzi_ch-15_p-14_s-6\",\n        \"xunzi_ch-15_p-14_s-7\",\n        \"xunzi_ch-15_p-14_s-8\",\n        \"xunzi_ch-15_p-14_s-9\",\n        \"xunzi_ch-15_p-14_s-10\",\n        \"xunzi_ch-15_p-14_s-11\",\n        \"xunzi_ch-15_p-14_s-12\",\n        \"xunzi_ch-15_p-14_s-13\",\n        \"xunzi_ch-15_p-14_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孫卿子說道：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，事至無悔而且止矣，成不可必啊。所以制號政令欲嚴以威，慶賞刑罰欲必以信，處舍收藏欲周以固，徙舉進退欲安以重，欲疾以速；窺敵觀變欲潛以深，欲伍以參；遇敵決戰必道吾所明，無道吾所疑：這就是儒家所稱的六術。無欲將而且惡廢，無急勝而且忘敗，無威內而且輕外，無見利而且不顧他的害，凡慮事欲孰而且用財欲泰：這就是儒家所稱的五權。所以不受命於主有三：可殺而且不可使處不完，可殺而且不可使擊不勝，可殺而且不可使欺百姓：這就是儒家所稱的三至。凡受命於主而且行三軍，三軍既定，百官得序，羣物皆正，則主不能喜，敵不能怒：這就是儒家所稱的至臣。慮必先事，而且申的以敬，慎終如始，終始如一：這就是儒家所稱的大吉。凡百事的成啊，必在敬的；他的敗啊，必在慢的。所以敬勝怠則吉，怠勝敬則滅；計勝欲則從，欲勝計則兇。戰如守，行如戰，有功如幸，敬謀無壙，敬事無壙，敬吏無壙，敬眾無壙，敬敵無壙：這就是儒家所稱的五無壙。謹行此六術、五權、三至，而且處的以恭敬無壙，這就是儒家所稱的天下的將，則通於神明矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孫卿子曰：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，事至無悔而止矣，成不可必也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孫」、「卿」、「子」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孫卿子曰知莫大乎棄疑行莫大乎無過事莫大乎無悔事至」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故制號政令欲嚴以威，慶賞刑罰欲必以信，處舍收藏欲周以固，徙舉進退欲安以重，欲疾以速」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-15\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 15,\n      \"canonicalText\": \"臨武君曰：善！請問王者之軍制？\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-15_s-1\",\n        \"xunzi_ch-15_p-15_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"臨武君說道：善！請問王的人或事的軍制？\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「臨武君曰：善」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「臨」、「武」、「君」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「臨武君曰善請問王者之軍制」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「請問王者之軍制」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 16,\n      \"canonicalText\": \"孫卿子曰：將死鼓，御死轡，百吏死職，士大夫死行列。聞鼓聲而進，聞金聲而退，順命為上，有功次之；令不進而進，猶令不退而退也，其罪惟均。不殺老弱，不獵禾稼，服者不禽，格者不捨，奔命者不獲。凡誅，非誅其百姓也，誅其亂百姓者也；百姓有扞其賊，則是亦賊也。以故順刃者生，蘇刃者死，奔命者貢。微子開封於宋，曹觸龍斷於軍，殷之服民，所以養生之者也，無異周人。故近者歌謳而樂之，遠者竭蹙而趨之，無幽閒闢陋之國，莫不趨使而安樂之，四海之內若一家，通達之屬莫不從服，夫是之謂人師。《詩》曰：「自西自東，自南自北，無思不服。」此之謂也。王者有誅而無戰，城守不攻，兵格不擊，上下相喜則慶之，不屠城，不潛軍，不留眾，師不越時。故亂者樂其政，不安其上，欲其至也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-16_s-1\",\n        \"xunzi_ch-15_p-16_s-2\",\n        \"xunzi_ch-15_p-16_s-3\",\n        \"xunzi_ch-15_p-16_s-4\",\n        \"xunzi_ch-15_p-16_s-5\",\n        \"xunzi_ch-15_p-16_s-6\",\n        \"xunzi_ch-15_p-16_s-7\",\n        \"xunzi_ch-15_p-16_s-8\",\n        \"xunzi_ch-15_p-16_s-9\",\n        \"xunzi_ch-15_p-16_s-10\",\n        \"xunzi_ch-15_p-16_s-11\",\n        \"xunzi_ch-15_p-16_s-12\",\n        \"xunzi_ch-15_p-16_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孫卿子說道：將死鼓，御死轡，百吏死職，士大夫死行列。聞鼓聲而且進，聞金聲而且退，順命為上，有功次的；令不進而且進，猶令不退而且退啊，他的罪惟均。不殺老弱，不獵禾稼，服的人或事不禽，格的人或事不捨，奔命的人或事不獲。凡誅，絕不是誅他的百姓啊，誅他的亂百姓的人或事啊；百姓有扞他的賊，則是亦賊啊。以所以順刃的人或事生，蘇刃的人或事死，奔命的人或事貢。微子開封於宋，曹觸龍斷於軍，殷的服民，所以養生的的人或事啊，無異周人。所以近的人或事歌謳而且樂的，遠的人或事竭蹙而且趨的，無幽閒闢陋的國，莫不趨使而且安樂的，四海的內若一家，通達的屬莫不從服，這就是儒家所說的人師。《詩》說道：自西自東，自南自北，無思不服。此的謂啊。王的人或事有誅而且無戰，城守不攻，兵格不擊，上下相喜則慶的，不屠城，不潛軍，不留眾，師不越時。所以亂的人或事樂他的政，不安他的上，欲他的至啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孫卿子曰：將死鼓，御死轡，百吏死職，士大夫死行列」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孫」、「卿」、「子」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孫卿子曰將死鼓御死轡百吏死職士大夫死行列聞鼓聲而」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「聞鼓聲而進，聞金聲而退，順命為上，有功次之」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-17\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 17,\n      \"canonicalText\": \"臨武君曰：善！\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-17_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"臨武君說道：善！\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「臨武君曰：善」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「臨」、「武」、「君」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「臨武君曰善」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「臨武君曰：善」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-18\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 18,\n      \"canonicalText\": \"陳囂問孫卿子曰：先生議兵，常以仁義為本；仁者愛人，義者循理，然則又何以兵為？凡所為有兵者，為爭奪也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-18_s-1\",\n        \"xunzi_ch-15_p-18_s-2\",\n        \"xunzi_ch-15_p-18_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"陳囂問孫卿子說道：先生議兵，常以仁愛之德道義正道為本；仁愛之德的人或事愛人，道義正道的人或事循理，然則又何以兵為？凡所為有兵的人或事，為爭奪啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「陳囂問孫卿子曰：先生議兵，常以仁義為本」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「陳」、「囂」、「問」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「陳囂問孫卿子曰先生議兵常以仁義為本仁者愛人義者循」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「仁者愛人，義者循理，然則又何以兵為」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 19,\n      \"canonicalText\": \"孫卿子曰：非汝所知也！彼仁者愛人，愛人故惡人之害之也；義者循理，循理故惡人之亂之也。彼兵者所以禁暴除害也，非爭奪也。故仁者之兵，所存者神，所過者化，若時雨之降，莫不說喜。是以堯伐驩兜，舜伐有苗，禹伐共工，湯伐有夏，文王伐崇，武王伐紂，此四帝兩王，皆以仁義之兵，行於天下也。故近者親其善，遠方慕其德，兵不血刃，遠邇來服，德盛於此，施及四極。《詩》曰：「淑人君子，其儀不忒。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-19_s-1\",\n        \"xunzi_ch-15_p-19_s-2\",\n        \"xunzi_ch-15_p-19_s-3\",\n        \"xunzi_ch-15_p-19_s-4\",\n        \"xunzi_ch-15_p-19_s-5\",\n        \"xunzi_ch-15_p-19_s-6\",\n        \"xunzi_ch-15_p-19_s-7\",\n        \"xunzi_ch-15_p-19_s-8\",\n        \"xunzi_ch-15_p-19_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孫卿子說道：絕不是汝所知啊！彼仁愛之德的人或事愛人，愛人所以惡人的害的啊；道義正道的人或事循理，循理所以惡人的亂的啊。彼兵的人或事所以禁暴除害啊，絕不是爭奪啊。所以仁愛之德的人或事的兵，所存的人或事神，所過的人或事化，若時雨的降，莫不說喜。是以堯伐驩兜，舜伐有苗，禹伐共工，湯伐有夏，文王伐崇，武王伐紂，此四帝兩王，皆以仁愛之德道義正道的兵，行於天下啊。所以近的人或事親他的善，遠方慕他的德行修養，兵不血刃，遠邇來服，德行修養盛於此，施及四極。《詩》說道：淑人君子，他的儀不忒。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孫卿子曰：非汝所知也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孫」、「卿」、「子」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孫卿子曰非汝所知也彼仁者愛人愛人故惡人之害之也義」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「彼仁者愛人，愛人故惡人之害之也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-20\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 20,\n      \"canonicalText\": \"李斯問孫卿子曰：秦四世有勝，兵強海內，威行諸侯，非以仁義為之也，以便從事而已。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-20_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"李斯問孫卿子說道：秦四世有勝，兵強海內，威行諸侯，絕不是以仁愛慈悲之德正義道義為的啊，以便從事而且已。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「李斯問孫卿子曰：秦四世有勝，兵強海內，威行諸侯，非以仁義為之也，以便從事而已」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「李」、「斯」、「問」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「李斯問孫卿子曰秦四世有勝兵強海內威行諸侯非以仁義」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「李斯問孫卿子曰：秦四世有勝，兵強海內，威行諸侯，非以仁義為之也，以便從事而已」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 21,\n      \"canonicalText\": \"孫卿子曰：非汝所知也！汝所謂便者，不便之便也；吾所謂仁義者，大便之便也。彼仁義者，所以脩政者也；政脩則民親其上，樂其君，而輕為之死。故曰：凡在於軍，將率末事也。秦四世有勝，諰諰然常恐天下之一合而軋己也，此所謂末世之兵，未有本統也。故湯之放桀也，非其逐之鳴條之時也；武王之誅紂也，非以甲子之朝而後勝之也，皆前行素脩也，所謂仁義之兵也。今女不求之於本，而索之於末，此世之所以亂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-21_s-1\",\n        \"xunzi_ch-15_p-21_s-2\",\n        \"xunzi_ch-15_p-21_s-3\",\n        \"xunzi_ch-15_p-21_s-4\",\n        \"xunzi_ch-15_p-21_s-5\",\n        \"xunzi_ch-15_p-21_s-6\",\n        \"xunzi_ch-15_p-21_s-7\",\n        \"xunzi_ch-15_p-21_s-8\",\n        \"xunzi_ch-15_p-21_s-9\",\n        \"xunzi_ch-15_p-21_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孫卿子說道：絕不是汝所知啊！汝所謂便的人或事，不便的便啊；吾所謂仁愛之德道義正道的人或事，大便的便啊。彼仁愛之德道義正道的人或事，所以脩政的人或事啊；政脩則民親他的上，樂他的君，而且輕為的死。所以說：凡在於軍，將率末事啊。秦四世有勝，諰諰然常恐天下的一合而且軋己啊，此所謂末世的兵，未有本統啊。所以湯的放桀啊，絕不是他的逐的鳴條的時啊；武王的誅紂啊，絕不是以甲子的朝而且後勝的啊，皆前行素脩啊，所謂仁愛之德道義正道的兵啊。今女不求的於本，而且索的於末，此世的所以亂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「孫卿子曰：非汝所知也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孫」、「卿」、「子」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孫卿子曰非汝所知也汝所謂便者不便之便也吾所謂仁義」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「汝所謂便者，不便之便也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-22\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 22,\n      \"canonicalText\": \"禮者、治辨之極也，強固之本也，威行之道也，功名之總也，王公由之所以得天下也，不由所以隕社稷也。故堅甲利兵不足以為勝，高城深池不足以為固，嚴令繁刑不足以為威。由其道則行，不由其道則廢。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-22_s-1\",\n        \"xunzi_ch-15_p-22_s-2\",\n        \"xunzi_ch-15_p-22_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"禮道義正道道德行修養規程的人或事、治辨的極啊，強固的本啊，威行的道啊，功名的總啊，王公由的所以得天下啊，不由所以隕社稷啊。所以堅甲利兵不足以為勝，高城深池不足以為固，嚴令繁刑不足以為威。由他的道則行，不由他的道則廢。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「禮者、治辨之極也，強固之本也，威行之道也，功名之總也，王公由之所以得天下也，不由所以隕社稷也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「禮」、「治」、「辨」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「禮者治辨之極也強固之本也威行之道也功名之總也王公」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故堅甲利兵不足以為勝，高城深池不足以為固，嚴令繁刑不足以為威」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 23,\n      \"canonicalText\": \"楚人鮫革犀兕以為甲，鞈堅如金石；宛鉅鐵矛，慘如蜂蠆，輕利僄遫，卒如飄風；然而兵殆於垂沙，唐蔑死。莊蹻起，楚分而為三四，是豈無堅甲利兵也哉！其所以統之者非其道故也。汝潁以為險，江漢以為池，限之以鄧林，緣之以方城；然而秦師至，而鄢郢舉，若振槁然，是豈無固塞隘阻也哉！其所以統之者非其道故也。紂刳比干，囚箕子，為炮烙刑，殺戮無時，臣下懍然莫必其命，然而周師至，而令不行乎下，不能用其民，是豈令不嚴，刑不繁也哉！其所以統之者非其道故也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-23_s-1\",\n        \"xunzi_ch-15_p-23_s-2\",\n        \"xunzi_ch-15_p-23_s-3\",\n        \"xunzi_ch-15_p-23_s-4\",\n        \"xunzi_ch-15_p-23_s-5\",\n        \"xunzi_ch-15_p-23_s-6\",\n        \"xunzi_ch-15_p-23_s-7\",\n        \"xunzi_ch-15_p-23_s-8\",\n        \"xunzi_ch-15_p-23_s-9\",\n        \"xunzi_ch-15_p-23_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"楚國人用鯊魚皮和犀牛皮做成鎧甲，堅硬得像金屬和石頭；使用宛地生產的精良鐵矛，毒烈得像蜜蜂和蠍子的尾刺，軍隊裝備輕便銳利、行動迅速，士兵衝鋒起來就像狂風一樣；然而楚軍卻在垂沙之戰中慘敗，主將唐蔑戰死。莊蹻發動叛亂，楚國四分五裂，難道是因為沒有堅固的鎧甲和鋒利的兵器嗎？是因為他們統御軍隊的方法不符合王道啊。楚國把汝水和潁水當作天險，把長江和漢水當作護城河，以鄧林作為邊界的屏障，沿著方城山修築防線；然而秦國軍隊一到，鄢、郢兩座都城就被攻克，就像搖落枯槁的樹葉一樣容易，難道是因為沒有堅固的要塞和險阻嗎？是因為他們統治國家的方法不符合王道啊。商紂王剖開比干的心，囚禁了箕子，設置了殘酷的炮烙之刑，殺戮沒有節制，臣子們恐懼得無法保證自己的性命，然而周武王的軍隊一到，商紂王的命令就無法下達，無法驅使他的百姓作戰，難道是因為命令不嚴厲、刑罰不繁多嗎？是因為他統治天下的方法不符合王道啊。\",\n        \"analysis\": \"【訓詁與名物】「鮫革犀兕」指用鯊魚皮和犀牛皮製成的鎧甲。「鞈」通「甲」。「宛鉅鐵矛」指宛地（南陽）出產的精良鐵矛。「蜂蠆」指蜜蜂與蠍子，比喻兵器有毒且銳利。「僄遫」指輕快敏捷。「振槁」指搖落枯槁的樹葉，比喻極其容易。「刳」指剖開。\\\\n【章法與結構】本段採取了極其工整的排比句式，連舉三個歷史案例（楚軍裝備精良卻敗於垂沙、楚國地勢險要卻失守鄢郢、商紂刑罰嚴酷卻亡國）。每個案例皆先極力鋪陳其優勢（兵器、地形、嚴刑），接著以「然而」發生轉折敘述其慘敗，最後以「是豈無……哉！其所以統之者非其道故也」作為一致的結語，論證層層推進，氣勢如虹。\\\\n【思想與義理】這段文字充分展現了荀子反對單純迷信武力、地形與嚴刑峻法的王道思想。荀子認為，堅甲利兵、險要地勢或嚴酷刑罰都只是外在的物質與手段，如果統治者背離了「道」（即仁義禮治），失去了民心與正當性，這些外在優勢都將毫無用處。治國與治軍的核心，始終在於政治的清明與人心的歸附。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 24,\n      \"canonicalText\": \"古之兵，戈矛弓矢而已矣，然而敵國不待試而詘；城郭不辨，溝池不抇，固塞不樹，機變不張；然而國晏然不畏外而固者，無它故焉，明道而鈞分之，時使而誠愛之，下之和上也如影嚮，有不由令者，然後俟之以刑。故刑一人而天下服，罪人不郵其上，知罪之在己也。是故刑罰省而威流，無它故焉，由其道故也。古者帝堯之治天下也，蓋殺一人，刑二人，而天下治。傳曰：「威厲而不試，刑錯而不用。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-24_s-1\",\n        \"xunzi_ch-15_p-24_s-2\",\n        \"xunzi_ch-15_p-24_s-3\",\n        \"xunzi_ch-15_p-24_s-4\",\n        \"xunzi_ch-15_p-24_s-5\",\n        \"xunzi_ch-15_p-24_s-6\",\n        \"xunzi_ch-15_p-24_s-7\",\n        \"xunzi_ch-15_p-24_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"古的兵，戈矛弓矢而且已矣，然而且敵國不待試而且詘；城郭不辨，溝池不抇，固塞不樹，機變不張；然而且國晏然不畏外而且固的人或事，無它所以焉，明道而且鈞分的，時使而且誠愛的，下的和上啊如影嚮，有不由令的人或事，然後俟的以刑。所以刑一人而且天下服，罪人不郵他的上，知罪的在己啊。正因為如此刑罰省而且威流，無它所以焉，由他的道所以啊。古的人或事帝堯的治天下啊，蓋殺一人，刑二人，而且天下治。傳說道：威厲而且不試，刑錯而且不用。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「古之兵，戈矛弓矢而已矣，然而敵國不待試而詘」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「古」、「兵」、「戈」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「古之兵戈矛弓矢而已矣然而敵國不待試而詘城郭不辨溝」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「城郭不辨，溝池不抇，固塞不樹，機變不張」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 25,\n      \"canonicalText\": \"凡人之動也，為賞慶為之，則見害傷焉止矣。故賞慶、刑罰、埶詐，不足以盡人之力，致人之死。為人主上者也，其所以接下之百姓者，無禮義忠信，焉慮率用賞慶、刑罰、埶詐，除阨其下，獲其功用而已矣。大寇則至，使之持危城則必畔，遇敵處戰則必北，勞苦煩辱則必奔，霍焉離耳，下反制其上。故賞慶、刑罰、埶詐之為道者，傭徒鬻賣之道也，不足以合大眾，美國家，故古之人羞而不道也。故厚德音以先之，明禮義以道之，致忠信以愛之，尚賢使能以次之，爵服慶賞以申之，時其事，輕其任，以調齊之，長養之，如保赤子。政令以定，風俗以一，有離俗不順其上，則百姓莫不敦惡，莫不毒孽，若祓不祥；然後刑於是起矣。是大刑之所加也，辱孰大焉！將以為利邪？則大刑加焉，身苟不狂惑戇陋，誰睹是而不改也哉！然後百姓曉然皆知循上之法，像上之志，而安樂之。於是有能化善、脩身、正行、積禮義、尊道德，百姓莫不貴敬，莫不親譽；然後賞於是起矣。是高爵豐祿之所加也，榮孰大焉！將以為害邪？則高爵豐祿以持養之；生民之屬，孰不願也！雕雕焉縣貴爵重賞於其前，縣明刑大辱於其後，雖欲無化，能乎哉！故民歸之如流水，所存者神，所為者化，而順，暴悍勇力之屬為之化而願，旁闢曲私之屬為之化而公，矜糾收繚之屬為之化而調，夫是之謂大化至一。《詩》曰：「王猶允塞，徐方既來。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-25_s-1\",\n        \"xunzi_ch-15_p-25_s-2\",\n        \"xunzi_ch-15_p-25_s-3\",\n        \"xunzi_ch-15_p-25_s-4\",\n        \"xunzi_ch-15_p-25_s-5\",\n        \"xunzi_ch-15_p-25_s-6\",\n        \"xunzi_ch-15_p-25_s-7\",\n        \"xunzi_ch-15_p-25_s-8\",\n        \"xunzi_ch-15_p-25_s-9\",\n        \"xunzi_ch-15_p-25_s-10\",\n        \"xunzi_ch-15_p-25_s-11\",\n        \"xunzi_ch-15_p-25_s-12\",\n        \"xunzi_ch-15_p-25_s-13\",\n        \"xunzi_ch-15_p-25_s-14\",\n        \"xunzi_ch-15_p-25_s-15\",\n        \"xunzi_ch-15_p-25_s-16\",\n        \"xunzi_ch-15_p-25_s-17\",\n        \"xunzi_ch-15_p-25_s-18\",\n        \"xunzi_ch-15_p-25_s-19\",\n        \"xunzi_ch-15_p-25_s-20\",\n        \"xunzi_ch-15_p-25_s-21\",\n        \"xunzi_ch-15_p-25_s-22\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"凡人的動啊，為賞慶為的，則見害傷焉止矣。所以賞慶、刑罰、埶詐，不足以盡人的力，致人的死。為人主上的人或事啊，他的所以接下的百姓的人或事，無禮道義正道道德行修養規程道義正道忠信，焉慮率用賞慶、刑罰、埶詐，除阨他的下，獲他的功用而且已矣。大寇則至，使的持危城則必畔，遇敵處戰則必北，勞苦煩辱則必奔，霍焉離耳，下反制他的上。所以賞慶、刑罰、埶詐的為道的人或事，傭徒鬻賣的道啊，不足以合大眾，美國家，所以古的人羞而且不道啊。所以厚德行修養音以先的，明禮道義正道道德行修養規程道義正道以道的，致忠信以愛的，尚賢使能以次的，爵服慶賞以申的，時他的事，輕他的任，以調齊的，長養的，如保赤子。政令以定，風俗以一，有離俗不順他的上，則百姓莫不敦惡，莫不毒孽，若祓不祥；然後刑於是起矣。是大刑的所加啊，辱孰大焉！將以為利邪？則大刑加焉，身苟不狂惑戇陋，誰睹是而且不改啊哉！然後百姓曉然皆知循上的典章法度，像上的志，而且安樂的。於是有能化善、脩身、正行、積禮道義正道道德行修養規程道義正道、尊道德行修養，百姓莫不貴敬，莫不親譽；然後賞於是起矣。是高爵豐祿的所加啊，榮孰大焉！將以為害邪？則高爵豐祿以持養的；生民的屬，孰不願啊！雕雕焉縣貴爵重賞於他的前，縣明刑大辱於他的後，雖欲無化，能乎哉！所以民歸的如流水，所存的人或事神，所為的人或事化，而且順，暴悍勇力的屬為的化而且願，旁闢曲私的屬為的化而且公，矜糾收繚的屬為的化而且調，這就是儒家所說的大化至一。《詩》說道：王猶允塞，徐方既來。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「凡人之動也，為賞慶為之，則見害傷焉止矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「凡」、「人」、「動」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「凡人之動也為賞慶為之則見害傷焉止矣故賞慶刑罰埶詐」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故賞慶、刑罰、埶詐，不足以盡人之力，致人之死」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 26,\n      \"canonicalText\": \"凡兼人者有三術：有以德兼人者，有以力兼人者，有以富兼人者。彼貴我名聲，美我德行，欲為我民，故闢門除塗，以迎吾入。因其民，襲其處，而百姓皆安。立法施令，莫不順比。是故得地而權彌重，兼人而兵俞強：是以德兼人者也。非貴我名聲也，非美我德行也，彼畏我威，劫我埶，故民雖有離心，不敢有畔慮，若是則戎甲俞眾，奉養必費。是故得地而權彌輕，兼人而兵俞弱：是以力兼人者也。非貴我名聲也，非美我德行也，用貧求富，用飢求飽，虛腹張口，來歸我食。若是，則必發夫掌窌之粟以食之，委之財貨以富之，立良有司以接之，已期三年，然後民可信也。是故得地而權彌輕，兼人而國俞貧：是以富兼人者也。故曰：以德兼人者王，以力兼人者弱，以富兼人者貧，古今一也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-26_s-1\",\n        \"xunzi_ch-15_p-26_s-2\",\n        \"xunzi_ch-15_p-26_s-3\",\n        \"xunzi_ch-15_p-26_s-4\",\n        \"xunzi_ch-15_p-26_s-5\",\n        \"xunzi_ch-15_p-26_s-6\",\n        \"xunzi_ch-15_p-26_s-7\",\n        \"xunzi_ch-15_p-26_s-8\",\n        \"xunzi_ch-15_p-26_s-9\",\n        \"xunzi_ch-15_p-26_s-10\",\n        \"xunzi_ch-15_p-26_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"凡兼人的人或事有三術：有以德行修養兼人的人或事，有以力兼人的人或事，有以富兼人的人或事。彼貴我名聲，美我德行修養行，欲為我民，所以闢門除塗，以迎吾入。因他的民，襲他的處，而且百姓皆安。立典章法度施令，莫不順比。正因為如此得地而且權彌重，兼人而且兵俞強：是以德行修養兼人的人或事啊。絕不是貴我名聲啊，絕不是美我德行修養行啊，彼畏我威，劫我埶，所以民雖有離心，不敢有畔慮，若是則戎甲俞眾，奉養必費。正因為如此得地而且權彌輕，兼人而且兵俞弱：是以力兼人的人或事啊。絕不是貴我名聲啊，絕不是美我德行修養行啊，用貧求富，用飢求飽，虛腹張口，來歸我食。若是，則必發夫掌窌的粟以食的，委的財貨以富的，立良有司以接的，已期三年，然後民可信啊。正因為如此得地而且權彌輕，兼人而且國俞貧：是以富兼人的人或事啊。所以說：以德行修養兼人的人或事王，以力兼人的人或事弱，以富兼人的人或事貧，古今一啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「凡兼人者有三術：有以德兼人者，有以力兼人者，有以富兼人者」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「凡」、「兼」、「人」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「凡兼人者有三術有以德兼人者有以力兼人者有以富兼人」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「彼貴我名聲，美我德行，欲為我民，故闢門除塗，以迎吾入」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"order\": 27,\n      \"canonicalText\": \"兼併易能也，唯堅凝之難焉。齊能並宋，而不能凝也，故魏奪之。燕能並齊，而不能凝也，故田單奪之。韓之上地，方數百里，完全富足而趨趙，趙不能凝也，故秦奪之。故能並之，而不能凝，則必奪；不能並之，又不能凝其有，則必亡。能凝之，則必能並之矣。得之則凝，兼併無強。古者湯以薄，武王以滈，皆百里之地也，天下為一，諸侯為臣，無他故焉，能凝之也。故凝士以禮，凝民以政；禮脩而士服，政平而民安；士服民安，夫是之謂大凝。以守則固，以徵則強，令行禁止，王者之事畢矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-15_p-27_s-1\",\n        \"xunzi_ch-15_p-27_s-2\",\n        \"xunzi_ch-15_p-27_s-3\",\n        \"xunzi_ch-15_p-27_s-4\",\n        \"xunzi_ch-15_p-27_s-5\",\n        \"xunzi_ch-15_p-27_s-6\",\n        \"xunzi_ch-15_p-27_s-7\",\n        \"xunzi_ch-15_p-27_s-8\",\n        \"xunzi_ch-15_p-27_s-9\",\n        \"xunzi_ch-15_p-27_s-10\",\n        \"xunzi_ch-15_p-27_s-11\",\n        \"xunzi_ch-15_p-27_s-12\",\n        \"xunzi_ch-15_p-27_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"兼併易能啊，唯堅凝的難焉。齊能並宋，而且不能凝啊，所以魏奪的。燕能並齊，而且不能凝啊，所以田單奪的。韓的上地，方數百里，完全富足而且趨趙，趙不能凝啊，所以秦奪的。所以能並的，而且不能凝，則必奪；不能並的，又不能凝他的有，則必亡。能凝的，則必能並的矣。得的則凝，兼併無強。古的人或事湯以薄，武王以滈，皆百里的地啊，天下為一，諸侯為臣，無他所以焉，能凝的啊。所以凝士以禮道義正道道德行修養規程，凝民以政；禮道義正道道德行修養規程脩而且士服，政平而且民安；士服民安，這就是儒家所說的大凝。以守則固，以徵則強，令行禁止，王的人或事的事畢矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈議兵〉。荀子立足於戰國後期的政治實踐，開篇「兼併易能也，唯堅凝之難焉」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「兼」、「併」、「易」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「兼併易能也唯堅凝之難焉齊能並宋而不能凝也故魏奪之」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「齊能並宋，而不能凝也，故魏奪之」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"xunzi_ch-15_p-1_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"臨武君與孫卿子議兵於趙孝成王前，王曰：請問兵要？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-2_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"臨武君對曰：上得天時，下得地利，觀敵之變動，後之發，先之至，此用兵之要術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-3_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"孫卿子曰：不然！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-3_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"臣所聞古之道，凡用兵攻戰之本，在乎壹民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-3_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"弓矢不調，則羿不能以中微；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-3_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"六馬不和，則造父不能以致遠；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-3_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"士民不親附，則湯武不能以必勝也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-3_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"故善附民者，是乃善用兵者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-3_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"故兵要在乎善附民而已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-4_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"臨武君曰：不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-4_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"兵之所貴者埶利也，所行者變詐也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-4_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"善用兵者，感忽悠闇，莫知其所從出。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-4_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"孫吳用之無敵於天下，豈必待附民哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"孫卿子曰：不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"臣之所道，仁者之兵，王者之志也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"君之所貴，權謀埶利也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"所行，攻奪變詐也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"諸侯之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"仁人之兵，不可詐也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"彼可詐者，怠慢者也，路亶者也，君臣上下之間，渙然有離德者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"故以桀詐桀，猶巧拙有幸焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"以桀詐堯，譬之：若以卵投石，以指撓沸；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"若赴水火，入焉焦沒耳。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"故仁人上下，百將一心，三軍同力；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"臣之於君也，下之於上也，若子之事父，弟之事兄，若手臂之扞頭目而覆胸腹也，詐而襲之，與先驚而後擊之，一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"且仁人之用十里之國，則將有百里之聽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"用百里之國，則將有千里之聽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 15,\n      \"canonicalText\": \"用千里之國，則將有四海之聽，必將聰明警戒和傳而一。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 16,\n      \"canonicalText\": \"故仁人之兵，聚則成卒，散則成列，延則若莫邪之長刃，嬰之者斷；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 17,\n      \"canonicalText\": \"兌則若莫邪之利鋒，當之者潰，圜居而方止，則若盤石然，觸之者角摧，案角鹿埵隴種東籠而退耳。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 18,\n      \"canonicalText\": \"且夫暴國之君，將誰與至哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 19,\n      \"canonicalText\": \"彼其所與至者，必其民也，而其民之親我歡若父母，其好我芬若椒蘭，彼反顧其上，則若灼黥，若讎仇；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-20\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 20,\n      \"canonicalText\": \"人之情，雖桀蹠，豈又肯為其所惡，賊其所好者哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-21\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 21,\n      \"canonicalText\": \"是猶使人之子孫自賊其父母也，彼必將來告之，夫又何可詐也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-22\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 22,\n      \"canonicalText\": \"故仁人用國日明，諸侯先順者安，後順者危，慮敵之者削，反之者亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-23\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 23,\n      \"canonicalText\": \"《詩》曰：「武王載發，有虔秉鉞；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-24\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 24,\n      \"canonicalText\": \"如火烈烈，則莫我敢遏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-5_s-25\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-5\",\n      \"order\": 25,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-6_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"孝成王、臨武君曰：善！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-6_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"請問王者之兵，設何道何行而可？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"孫卿子曰：凡在大王，將率末事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"臣請遂道王者諸侯強弱存亡之效，安危之埶：君賢者其國治，君不能者其國亂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"隆禮貴義者其國治，簡禮賤義者其國亂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"治者強，亂者弱，是強弱之本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"上足卬則下可用也，上不卬則下不可用也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"下可用則強，下不可用則弱，是強弱之常也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"隆禮效功，上也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"重祿貴節，次也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"上功賤節，下也，是強弱之凡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 10,\n      \"canonicalText\": \"好士者強，不好士者弱；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 11,\n      \"canonicalText\": \"愛民者強，不愛民者弱；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 12,\n      \"canonicalText\": \"政令信者強，政令不信者弱；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 13,\n      \"canonicalText\": \"民齊者強，民不齊者弱；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 14,\n      \"canonicalText\": \"賞重者強，賞輕者弱；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 15,\n      \"canonicalText\": \"刑威者強，刑侮者弱；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 16,\n      \"canonicalText\": \"械用兵革攻完便利者強，械用兵革窳楛不便利者弱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 17,\n      \"canonicalText\": \"重用兵者強，輕用兵者弱；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-7_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-7\",\n      \"order\": 18,\n      \"canonicalText\": \"權出一者強，權出二者弱，是強弱之常也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-8_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"齊人隆技擊，其技也，得一首者，則賜贖錙金，無本賞矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-8_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"是事小敵毳，則偷可用也，事大敵堅，則渙然離耳。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-8_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"若飛鳥然，傾側反覆無日，是亡國之兵也，兵莫弱是矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-8_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"是其去賃市傭而戰之幾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-9_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"魏氏之武卒，以度取之，衣三屬之甲，操十二石之弩，負服矢五十個，置戈其上，冠冑帶劍，贏三日之糧，日中而趨百里，中試則復其戶，利其田宅，是數年而衰，而未可奪也，改造則不易周也，是故地雖大，其稅必寡，是危國之兵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-10_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"秦人其生民郟阨，其使民也酷烈，劫之以埶，隱之以阨，忸之以慶賞，酋之以刑罰，使天下之民，所以要利於上者，非鬥無由也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-10_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"阨而用之，得而後功之，功賞相長也，五甲首而隸五家，是最為眾強長久，多地以正，故四世有勝，非幸也，數也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"故齊之技擊，不可以遇魏氏之武卒；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"魏氏之武卒，不可以遇秦之銳士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"秦之銳士，不可以當桓文之節制；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"桓文之節制，不可以敵湯武之仁義；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"有遇之者，若以焦熬投石焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"兼是數國者，皆幹賞蹈利之兵也，傭徒鬻賣之道也，未有貴上安制綦節之理也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"諸侯有能微妙之以節，則作而兼殆之耳。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"故招近募選，隆埶詐，尚功利，是漸之也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 9,\n      \"canonicalText\": \"禮義教化，是齊之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 10,\n      \"canonicalText\": \"故以詐遇詐，猶有巧拙焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 11,\n      \"canonicalText\": \"以詐遇齊，闢之猶以錐刀墮太山也，非天下之愚人莫敢試。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 12,\n      \"canonicalText\": \"故王者之兵不試。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 13,\n      \"canonicalText\": \"湯武之誅桀紂也，拱挹指麾，而強暴之國莫不趨使，誅桀紂若誅獨夫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 14,\n      \"canonicalText\": \"故泰誓曰：「獨夫紂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 15,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 16,\n      \"canonicalText\": \"故兵大齊則制天下，小齊則治鄰敵。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 17,\n      \"canonicalText\": \"若夫招近募選，隆埶詐，尚功利之兵，則勝不勝無常，代翕代張，代存代亡，相為雌雄耳矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-11_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-11\",\n      \"order\": 18,\n      \"canonicalText\": \"夫是之謂盜兵，君子不由也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-12_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"故齊之田單，楚之莊蹻，秦之衛鞅，燕之繆蟣，是皆世俗所謂善用兵者也，是其巧拙強弱，則未有以相君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-12_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"若其道一也，未及和齊也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-12_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"掎契司詐，權謀傾覆，未免盜兵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-12_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"齊桓、晉文、楚莊、吳闔閭、越勾踐是皆和齊之兵也，可謂入其域矣，然而未有本統也，故可以霸而不可以王；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-12_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"是強弱之效也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-13_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"孝成王、臨武君曰善！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-13_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"請問為將？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"孫卿子曰：知莫大乎棄疑，行莫大乎無過，事莫大乎無悔，事至無悔而止矣，成不可必也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"故制號政令欲嚴以威，慶賞刑罰欲必以信，處舍收藏欲周以固，徙舉進退欲安以重，欲疾以速；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"窺敵觀變欲潛以深，欲伍以參；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"遇敵決戰必道吾所明，無道吾所疑：夫是之謂六術。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 5,\n      \"canonicalText\": \"無欲將而惡廢，無急勝而忘敗，無威內而輕外，無見利而不顧其害，凡慮事欲孰而用財欲泰：夫是之謂五權。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 6,\n      \"canonicalText\": \"所以不受命於主有三：可殺而不可使處不完，可殺而不可使擊不勝，可殺而不可使欺百姓：夫是之謂三至。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 7,\n      \"canonicalText\": \"凡受命於主而行三軍，三軍既定，百官得序，羣物皆正，則主不能喜，敵不能怒：夫是之謂至臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 8,\n      \"canonicalText\": \"慮必先事，而申之以敬，慎終如始，終始如一：夫是之謂大吉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 9,\n      \"canonicalText\": \"凡百事之成也，必在敬之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 10,\n      \"canonicalText\": \"其敗也，必在慢之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 11,\n      \"canonicalText\": \"故敬勝怠則吉，怠勝敬則滅；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 12,\n      \"canonicalText\": \"計勝欲則從，欲勝計則兇。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 13,\n      \"canonicalText\": \"戰如守，行如戰，有功如幸，敬謀無壙，敬事無壙，敬吏無壙，敬眾無壙，敬敵無壙：夫是之謂五無壙。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-14_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-14\",\n      \"order\": 14,\n      \"canonicalText\": \"謹行此六術、五權、三至，而處之以恭敬無壙，夫是之謂天下之將，則通於神明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-15_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"臨武君曰：善！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-15_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"請問王者之軍制？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"孫卿子曰：將死鼓，御死轡，百吏死職，士大夫死行列。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"聞鼓聲而進，聞金聲而退，順命為上，有功次之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"令不進而進，猶令不退而退也，其罪惟均。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"不殺老弱，不獵禾稼，服者不禽，格者不捨，奔命者不獲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"凡誅，非誅其百姓也，誅其亂百姓者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"百姓有扞其賊，則是亦賊也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"以故順刃者生，蘇刃者死，奔命者貢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"微子開封於宋，曹觸龍斷於軍，殷之服民，所以養生之者也，無異周人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 9,\n      \"canonicalText\": \"故近者歌謳而樂之，遠者竭蹙而趨之，無幽閒闢陋之國，莫不趨使而安樂之，四海之內若一家，通達之屬莫不從服，夫是之謂人師。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 10,\n      \"canonicalText\": \"《詩》曰：「自西自東，自南自北，無思不服。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 11,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 12,\n      \"canonicalText\": \"王者有誅而無戰，城守不攻，兵格不擊，上下相喜則慶之，不屠城，不潛軍，不留眾，師不越時。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-16_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-16\",\n      \"order\": 13,\n      \"canonicalText\": \"故亂者樂其政，不安其上，欲其至也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-17_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"臨武君曰：善！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-18_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"陳囂問孫卿子曰：先生議兵，常以仁義為本；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-18_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"仁者愛人，義者循理，然則又何以兵為？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-18_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"凡所為有兵者，為爭奪也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"孫卿子曰：非汝所知也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"彼仁者愛人，愛人故惡人之害之也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"義者循理，循理故惡人之亂之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 4,\n      \"canonicalText\": \"彼兵者所以禁暴除害也，非爭奪也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 5,\n      \"canonicalText\": \"故仁者之兵，所存者神，所過者化，若時雨之降，莫不說喜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 6,\n      \"canonicalText\": \"是以堯伐驩兜，舜伐有苗，禹伐共工，湯伐有夏，文王伐崇，武王伐紂，此四帝兩王，皆以仁義之兵，行於天下也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 7,\n      \"canonicalText\": \"故近者親其善，遠方慕其德，兵不血刃，遠邇來服，德盛於此，施及四極。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 8,\n      \"canonicalText\": \"《詩》曰：「淑人君子，其儀不忒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-19_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-19\",\n      \"order\": 9,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-20_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"李斯問孫卿子曰：秦四世有勝，兵強海內，威行諸侯，非以仁義為之也，以便從事而已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"孫卿子曰：非汝所知也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 2,\n      \"canonicalText\": \"汝所謂便者，不便之便也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 3,\n      \"canonicalText\": \"吾所謂仁義者，大便之便也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 4,\n      \"canonicalText\": \"彼仁義者，所以脩政者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 5,\n      \"canonicalText\": \"政脩則民親其上，樂其君，而輕為之死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 6,\n      \"canonicalText\": \"故曰：凡在於軍，將率末事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 7,\n      \"canonicalText\": \"秦四世有勝，諰諰然常恐天下之一合而軋己也，此所謂末世之兵，未有本統也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 8,\n      \"canonicalText\": \"故湯之放桀也，非其逐之鳴條之時也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 9,\n      \"canonicalText\": \"武王之誅紂也，非以甲子之朝而後勝之也，皆前行素脩也，所謂仁義之兵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-21_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-21\",\n      \"order\": 10,\n      \"canonicalText\": \"今女不求之於本，而索之於末，此世之所以亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-22_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"禮者、治辨之極也，強固之本也，威行之道也，功名之總也，王公由之所以得天下也，不由所以隕社稷也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-22_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-22\",\n      \"order\": 2,\n      \"canonicalText\": \"故堅甲利兵不足以為勝，高城深池不足以為固，嚴令繁刑不足以為威。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-22_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-22\",\n      \"order\": 3,\n      \"canonicalText\": \"由其道則行，不由其道則廢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 1,\n      \"canonicalText\": \"楚人鮫革犀兕以為甲，鞈堅如金石；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 2,\n      \"canonicalText\": \"宛鉅鐵矛，慘如蜂蠆，輕利僄遫，卒如飄風；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 3,\n      \"canonicalText\": \"然而兵殆於垂沙，唐蔑死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 4,\n      \"canonicalText\": \"莊蹻起，楚分而為三四，是豈無堅甲利兵也哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 5,\n      \"canonicalText\": \"其所以統之者非其道故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 6,\n      \"canonicalText\": \"汝潁以為險，江漢以為池，限之以鄧林，緣之以方城；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 7,\n      \"canonicalText\": \"然而秦師至，而鄢郢舉，若振槁然，是豈無固塞隘阻也哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 8,\n      \"canonicalText\": \"其所以統之者非其道故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 9,\n      \"canonicalText\": \"紂刳比干，囚箕子，為炮烙刑，殺戮無時，臣下懍然莫必其命，然而周師至，而令不行乎下，不能用其民，是豈令不嚴，刑不繁也哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-23_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-23\",\n      \"order\": 10,\n      \"canonicalText\": \"其所以統之者非其道故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-24\",\n      \"order\": 1,\n      \"canonicalText\": \"古之兵，戈矛弓矢而已矣，然而敵國不待試而詘；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-24\",\n      \"order\": 2,\n      \"canonicalText\": \"城郭不辨，溝池不抇，固塞不樹，機變不張；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-24\",\n      \"order\": 3,\n      \"canonicalText\": \"然而國晏然不畏外而固者，無它故焉，明道而鈞分之，時使而誠愛之，下之和上也如影嚮，有不由令者，然後俟之以刑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-24\",\n      \"order\": 4,\n      \"canonicalText\": \"故刑一人而天下服，罪人不郵其上，知罪之在己也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-24\",\n      \"order\": 5,\n      \"canonicalText\": \"是故刑罰省而威流，無它故焉，由其道故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-24\",\n      \"order\": 6,\n      \"canonicalText\": \"古者帝堯之治天下也，蓋殺一人，刑二人，而天下治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-24\",\n      \"order\": 7,\n      \"canonicalText\": \"傳曰：「威厲而不試，刑錯而不用。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-24_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-24\",\n      \"order\": 8,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 1,\n      \"canonicalText\": \"凡人之動也，為賞慶為之，則見害傷焉止矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 2,\n      \"canonicalText\": \"故賞慶、刑罰、埶詐，不足以盡人之力，致人之死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 3,\n      \"canonicalText\": \"為人主上者也，其所以接下之百姓者，無禮義忠信，焉慮率用賞慶、刑罰、埶詐，除阨其下，獲其功用而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 4,\n      \"canonicalText\": \"大寇則至，使之持危城則必畔，遇敵處戰則必北，勞苦煩辱則必奔，霍焉離耳，下反制其上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 5,\n      \"canonicalText\": \"故賞慶、刑罰、埶詐之為道者，傭徒鬻賣之道也，不足以合大眾，美國家，故古之人羞而不道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 6,\n      \"canonicalText\": \"故厚德音以先之，明禮義以道之，致忠信以愛之，尚賢使能以次之，爵服慶賞以申之，時其事，輕其任，以調齊之，長養之，如保赤子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 7,\n      \"canonicalText\": \"政令以定，風俗以一，有離俗不順其上，則百姓莫不敦惡，莫不毒孽，若祓不祥；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 8,\n      \"canonicalText\": \"然後刑於是起矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 9,\n      \"canonicalText\": \"是大刑之所加也，辱孰大焉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 10,\n      \"canonicalText\": \"將以為利邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 11,\n      \"canonicalText\": \"則大刑加焉，身苟不狂惑戇陋，誰睹是而不改也哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 12,\n      \"canonicalText\": \"然後百姓曉然皆知循上之法，像上之志，而安樂之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 13,\n      \"canonicalText\": \"於是有能化善、脩身、正行、積禮義、尊道德，百姓莫不貴敬，莫不親譽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 14,\n      \"canonicalText\": \"然後賞於是起矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 15,\n      \"canonicalText\": \"是高爵豐祿之所加也，榮孰大焉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 16,\n      \"canonicalText\": \"將以為害邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 17,\n      \"canonicalText\": \"則高爵豐祿以持養之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 18,\n      \"canonicalText\": \"生民之屬，孰不願也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 19,\n      \"canonicalText\": \"雕雕焉縣貴爵重賞於其前，縣明刑大辱於其後，雖欲無化，能乎哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-20\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 20,\n      \"canonicalText\": \"故民歸之如流水，所存者神，所為者化，而順，暴悍勇力之屬為之化而願，旁闢曲私之屬為之化而公，矜糾收繚之屬為之化而調，夫是之謂大化至一。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-21\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 21,\n      \"canonicalText\": \"《詩》曰：「王猶允塞，徐方既來。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-25_s-22\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-25\",\n      \"order\": 22,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 1,\n      \"canonicalText\": \"凡兼人者有三術：有以德兼人者，有以力兼人者，有以富兼人者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 2,\n      \"canonicalText\": \"彼貴我名聲，美我德行，欲為我民，故闢門除塗，以迎吾入。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 3,\n      \"canonicalText\": \"因其民，襲其處，而百姓皆安。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 4,\n      \"canonicalText\": \"立法施令，莫不順比。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 5,\n      \"canonicalText\": \"是故得地而權彌重，兼人而兵俞強：是以德兼人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 6,\n      \"canonicalText\": \"非貴我名聲也，非美我德行也，彼畏我威，劫我埶，故民雖有離心，不敢有畔慮，若是則戎甲俞眾，奉養必費。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 7,\n      \"canonicalText\": \"是故得地而權彌輕，兼人而兵俞弱：是以力兼人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 8,\n      \"canonicalText\": \"非貴我名聲也，非美我德行也，用貧求富，用飢求飽，虛腹張口，來歸我食。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 9,\n      \"canonicalText\": \"若是，則必發夫掌窌之粟以食之，委之財貨以富之，立良有司以接之，已期三年，然後民可信也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 10,\n      \"canonicalText\": \"是故得地而權彌輕，兼人而國俞貧：是以富兼人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-26_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-26\",\n      \"order\": 11,\n      \"canonicalText\": \"故曰：以德兼人者王，以力兼人者弱，以富兼人者貧，古今一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 1,\n      \"canonicalText\": \"兼併易能也，唯堅凝之難焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 2,\n      \"canonicalText\": \"齊能並宋，而不能凝也，故魏奪之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 3,\n      \"canonicalText\": \"燕能並齊，而不能凝也，故田單奪之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 4,\n      \"canonicalText\": \"韓之上地，方數百里，完全富足而趨趙，趙不能凝也，故秦奪之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 5,\n      \"canonicalText\": \"故能並之，而不能凝，則必奪；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 6,\n      \"canonicalText\": \"不能並之，又不能凝其有，則必亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 7,\n      \"canonicalText\": \"能凝之，則必能並之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 8,\n      \"canonicalText\": \"得之則凝，兼併無強。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 9,\n      \"canonicalText\": \"古者湯以薄，武王以滈，皆百里之地也，天下為一，諸侯為臣，無他故焉，能凝之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 10,\n      \"canonicalText\": \"故凝士以禮，凝民以政；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 11,\n      \"canonicalText\": \"禮脩而士服，政平而民安；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 12,\n      \"canonicalText\": \"士服民安，夫是之謂大凝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-15_p-27_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-15\",\n      \"passageId\": \"xunzi_ch-15_p-27\",\n      \"order\": 13,\n      \"canonicalText\": \"以守則固，以徵則強，令行禁止，王者之事畢矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
